//variable_set('rules_populate_user_expertise__counter',$nid);
if (!function_exists('labor_merit_rewarder')) {
	function labor_merit_rewarder($purchased_product_id,$userid,$merits) {
	
			$user = user_load($userid);
			$roles = $user->roles;
			$arkeys = array_keys($roles);
			
			//do not process banned users
			if (in_array(5,$arkeys)) {
				return;
			}
	
			$result = db_query("SELECT DISTINCT c.field_classification_tid AS cat, SUM(h.field_hours_worked_value) AS hours
			FROM {node} node
			LEFT JOIN {field_data_field_project} p ON node.nid = p.entity_id AND (p.entity_type = 'node' AND p.deleted = '0')
			LEFT JOIN {field_data_field_classification} c ON node.nid = c.entity_id AND (c.entity_type = 'node' AND c.deleted = '0')
			LEFT JOIN {field_data_field_hours_worked} h ON node.nid = h.entity_id AND (h.entity_type = 'node' AND h.deleted = '0')
			WHERE p.field_project_target_id = :prid
			AND c.delta = 0
			AND node.uid = :uid 
			AND node.status = '1'
			AND node.type IN  ('work_report')
			GROUP BY c.field_classification_tid", array(':prid' => $purchased_product_id, ':uid' => $userid));
			$resarray = $result->fetchAll();

			$total_time = 0;
			foreach ($resarray as $row) {
				$total_time += $row->hours;
			}
			if ($total_time > 0) {
				foreach ($resarray as $row) {
		
					//load the expert table node corresponding to the current category in order to find its existing Merit value
					$result = db_query("SELECT node.nid AS nid, m.field_merits_value AS merits
					FROM {node} node
					LEFT JOIN {field_data_field_expert} x ON node.nid = x.entity_id AND (x.entity_type = 'node' AND x.deleted = '0')
					LEFT JOIN {field_data_field_category} c ON node.nid = c.entity_id AND (c.entity_type = 'node' AND c.deleted = '0')
					LEFT JOIN {field_data_field_merits} m ON node.nid = m.entity_id AND (m.entity_type = 'node' AND m.deleted = '0')
					WHERE node.type = 'user_expertise'
					AND field_expert_target_id = :uid
					AND c.field_category_tid = :cat
					", array(':uid' => $userid, ':cat' => $row->cat));

					$record = $result->fetchAssoc();
					//for some users and category IDs we will have to create a new user_expertise node			
					if (empty($record)) {
						$node = new stdClass();
						$node->type = 'user_expertise';
						$node->title = 'UX-' . $userid . '-' . $row->cat;
						$node->language = LANGUAGE_NONE;
						node_object_prepare($node);
						$node->uid = $userid;

						$now = time();

						$node->created = $now;
						$node->changed = $now;

						$node->field_expert[LANGUAGE_NONE][0]['target_id'] = $userid;
						$node->field_category[LANGUAGE_NONE][0]['tid'] = $row->cat;

						$old_merits = 0;
						$node->field_merits[LANGUAGE_NONE][0]['value'] = $old_merits;

						$node = node_submit($node);
						node_save($node);
						$nid = $node->nid;

					}
					else {
						$old_merits = $record['merits'];
						$nid = $record['nid'];
					}

					$this_ratio = $row->hours / $total_time;
					$merits2add = $this_ratio * $merits;
			
					$cur_merits = $old_merits + $merits2add;

					//updating the node with new merit value
					$node = node_load($nid);
					$node->changed = time(); // Force timestamp
					$xobject = entity_metadata_wrapper('node', $node);
					$xobject->field_merits = $cur_merits;
					$xobject->save();

				}
			}
	}
}

